local TweenService = game:GetService("TweenService")
local Connection = require(script.Parent.Parent.Connection)
local module = {}
module.__index = module

function module.new(btnOrKey)
    local self = {}
    setmetatable(self, module)
    local conneciton = Connection.All[btnOrKey] and Connection.All[btnOrKey][1]

    if conneciton then
        self.Target = conneciton.Target
        self.Source = conneciton.Source
    elseif typeof(btnOrKey) == "Instance" then
		self.Target = function()
			local conneciton = Connection.All[btnOrKey] and Connection.All[btnOrKey][1]
			if conneciton then
				conneciton.Target()
			else
				warn("No connection found for " .. btnOrKey:GetFullName())
			end
        end
        self.Source = btnOrKey
    end
    self._connections = {}

    self._event = Instance.new("BindableEvent")
    self.Triggerred = self._event.Event

    return self
end

function module:Show(focus)

    local uiObj = self.Source
    local pos = uiObj.AbsolutePosition
    local center = uiObj.AbsoluteSize / 2 + pos

    local extand = math.ceil(focus:FindFirstChild("UIStroke").Thickness / 2)

    local newSize = UDim2.new(0, uiObj.AbsoluteSize.X + extand, 0, uiObj.AbsoluteSize.Y + extand)
    local newPos = UDim2.new(0, center.X, 0, center.Y)
    local dt = focus.Visible and .5 or 0
    
    local t1
    t1 = TweenService:Create(focus, TweenInfo.new(dt), {Size = newSize, Position = newPos})
    -- t2 = TweenService:Create(border, TweenInfo.new(dt), {Size = newSize, Position = newPos})
    focus.Visible = true
    -- border.Visible = true

    local c5 = t1.Completed:Connect(function(playbackState)
		if playbackState == Enum.PlaybackState.Completed then
			
			local c1 = game["Run Service"].RenderStepped:Connect(function()
				local pos = uiObj.AbsolutePosition
				local center = uiObj.AbsoluteSize / 2 + pos
				focus.Position = UDim2.new(0, center.X, 0, center.Y)
				
				focus.Size = UDim2.new(0, uiObj.AbsoluteSize.X + extand, 0, uiObj.AbsoluteSize.Y + extand)
			end)
		
            local c2 = focus.InputEnded:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    if self._connections then
                        for i, v in pairs(self._connections) do
                            v:Disconnect()
                        end
                        table.clear(self._connections)
                    end
                    if self._event then
                        self.Target()
                        self._event:Fire()
                    end
                end
            end)

            for i, v in pairs(focus:GetChildren()) do
                if v:IsA("Frame") then
                    local c4 = v.InputEnded:Connect(function(input)
                        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                            focus.UIScale.Scale = 1
                            TweenService:Create(focus.UIScale, TweenInfo.new(.15, Enum.EasingStyle.Sine, Enum.EasingDirection.Out, 1, true), {Scale = 1.1}):Play()
                        end
                    end)
                    table.insert(self._connections, c4)
                end
            end
        
            table.insert(self._connections, c1)
            table.insert(self._connections, c2)
            --table.insert(self._connections, c3)
        end
    end)
    table.insert(self._connections, c5)
    
    t1:Play()

    return center, newSize
end

function module:SetNext(guidance)
    self._next = guidance
end

function module:Destroy()
    if self._connections then
        for i, v in pairs(self._connections) do
            v:Disconnect()
        end
        table.clear(self._connections)
    end
    self._event:Destroy()
    self._event = nil
    self._next = nil
    self.Source = nil
    self.Target = nil
    self.Triggerred = nil
    self._connections = nil
    self = nil
end

return module